from elftools.elf.elffile import ELFFile

with open('/tmp/libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)

    # Check which section contains these addresses
    for section in elf.iter_sections():
        start = section['sh_addr']
        size = section['sh_size']
        if start <= 0x2f4b20 < start + size:
            print(f"0x2f4b20 is in section {section.name} (0x{start:x} - 0x{start+size:x})")
        if start <= 0x2f4c84 < start + size:
            print(f"0x2f4c84 is in section {section.name} (0x{start:x} - 0x{start+size:x})")

    # Also check 0x2c1a40
    for section in elf.iter_sections():
        start = section['sh_addr']
        size = section['sh_size']
        if start <= 0x2c1a40 < start + size:
            print(f"0x2c1a40 is in section {section.name} (0x{start:x} - 0x{start+size:x})")

    # Check DWARF for these addresses
    if elf.has_dwarf_info():
        di = elf.get_dwarf_info()
        for CU in di.iter_CUs():
            lt = di.line_program_for_CU(CU)
            if lt:
                for entry in lt.get_entries():
                    state = entry.state
                    if state and not state.end_sequence:
                        if state.address in [0x2f4b20, 0x2f4c84]:
                            print(f"DWARF line: 0x{state.address:x} -> {lt['file_entry'][state.file-1].name}:{state.line}")
PYEOF

